	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRegexControlEdges67.cls"), "@IsTest private class GladeRegexControlEdges67 {\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every edge operation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Edge observation exceeds bound');verifyExactEdges(rows);}\nprivate static void observe(String sourcePattern,Boolean matches){\nList<Object> rows=new List<Object>();Map<String,Object> row=new Map<String,Object>{'pattern'=>sourcePattern,'utf16Length'=>sourcePattern.length(),'operation'=>matches?'matches':'compile'};\ntry{if(matches){row.put('value',Pattern.matches(sourcePattern,'a'));}else{Pattern compiled=Pattern.compile(sourcePattern);row.put('returned',compiled!=null);}}\ncatch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\nrows.add(row);finish(rows,1);\n}\n@IsTest static void compile_lineFeed(){observe('ab\\n[',false);}\n@IsTest static void compile_crlf(){observe('ab\\r\\n[',false);}\n@IsTest static void compile_tab(){observe('ab\\t[',false);}\n@IsTest static void compile_carriageReturn(){observe('ab\\r[',false);}\n@IsTest static void compile_formFeed(){observe('ab\\f[',false);}\n@IsTest static void compile_backspace(){observe('ab\\b[',false);}\n@IsTest static void compile_astralLineFeed(){observe('😀\\n[',false);}\n@IsTest static void matches_lineFeed(){observe('ab\\n[',true);}\n@IsTest static void matches_crlf(){observe('ab\\r\\n[',true);}\n@IsTest static void matches_tab(){observe('ab\\t[',true);}\n@IsTest static void matches_carriageReturn(){observe('ab\\r[',true);}\n@IsTest static void matches_formFeed(){observe('ab\\f[',true);}\n@IsTest static void matches_backspace(){observe('ab\\b[',true);}\n@IsTest static void matches_astralLineFeed(){observe('😀\\n[',true);}\n\nprivate static void verifyExactEdges(List<Object> rows){\nSystem.assert(rows.size()>0,'Expected at least one observed row');\nMap<String,Object> first=(Map<String,Object>)rows[0];\nString expectedJSON;\nif((String)first.get('pattern') == '😀\\n[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 2\\\\n😀\\\\n[\\\\n  ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"😀\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\b[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\b[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"ab\\\\b[\"}]';\nelse if((String)first.get('pattern') == 'ab\\r[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\r[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"ab\\\\r[\"}]';\nelse if((String)first.get('pattern') == 'ab\\r\\n[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 4\\\\nab\\\\r\\\\n[\\\\n    ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":5,\"pattern\":\"ab\\\\r\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\f[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\f[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"ab\\\\f[\"}]';\nelse if((String)first.get('pattern') == 'ab\\n[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\n[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"ab\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\t[' && (String)first.get('operation') == 'compile')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\t[\\\\n  \\\\t^\",\"type\":\"System.StringException\",\"operation\":\"compile\",\"utf16Length\":4,\"pattern\":\"ab\\\\t[\"}]';\nelse if((String)first.get('pattern') == '😀\\n[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 2\\\\n😀\\\\n[\\\\n  ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"😀\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\b[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\b[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"ab\\\\b[\"}]';\nelse if((String)first.get('pattern') == 'ab\\r[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\r[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"ab\\\\r[\"}]';\nelse if((String)first.get('pattern') == 'ab\\r\\n[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 4\\\\nab\\\\r\\\\n[\\\\n    ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":5,\"pattern\":\"ab\\\\r\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\f[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\f[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"ab\\\\f[\"}]';\nelse if((String)first.get('pattern') == 'ab\\n[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\n[\\\\n   ^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"ab\\\\n[\"}]';\nelse if((String)first.get('pattern') == 'ab\\t[' && (String)first.get('operation') == 'matches')expectedJSON='[{\"message\":\"Invalid regex: Unclosed character class near index 3\\\\nab\\\\t[\\\\n  \\\\t^\",\"type\":\"System.StringException\",\"operation\":\"matches\",\"utf16Length\":4,\"pattern\":\"ab\\\\t[\"}]';\nelse {System.assert(false,'Unknown edge input/operation');return;}\ncompareExactEdgeValue(JSON.deserializeUntyped(expectedJSON),JSON.deserializeUntyped(JSON.serialize(rows)),'rows');\n}\nprivate static void compareExactEdgeValue(Object expected,Object actual,String path){\nif(expected instanceof Map<String,Object>){\n System.assert(actual instanceof Map<String,Object>,'Expected map '+path);\n Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n System.assertEquals(want.keySet(),got.keySet(),'Complete keys '+path);\n for(String key:want.keySet())compareExactEdgeValue(want.get(key),got.get(key),path+'.'+key);\n}else if(expected instanceof List<Object>){\n System.assert(actual instanceof List<Object>,'Expected list '+path);\n List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n System.assertEquals(want.size(),got.size(),'Complete phase population '+path);\n for(Integer i=0;i<want.size();i++)compareExactEdgeValue(want[i],got[i],path+'['+i+']');\n}else System.assertEquals(expected,actual,'Exact value '+path);\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRegexControlEdges67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
